-- k8s 세트 383. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_helm_chart_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 383, 'Helm 차트 직접 만들기 손연습: create, show values, template, --set, -f, lint, package, install, rollback', '저장소에서 받아 쓰는 데서 한 걸음 나아가, 차트를 직접 다뤄 봅니다. 뼈대를 만들고(helm create), 기본값을 확인하고, 설치 없이 YAML 을 렌더링해 보고(helm template), --set 과 값 파일(-f)로 값을 바꾸고, helm lint 로 오류를 고치고, 차트를 패키징한 뒤 로컬 차트를 설치하고 업그레이드·롤백합니다.', 'k8s', 'k8s'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 383);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 1, '차트 뼈대 만들기 (helm create)', '**배경** — **차트(chart)** 는 쿠버네티스 YAML 을 묶은 "설치 꾸러미"입니다. 폴더 하나이고, `Chart.yaml`(이름·버전), `values.yaml`(기본 설정값), `templates/`(값이 들어갈 자리가 있는 YAML 틀)로 이루어집니다. `helm create 이름` 이 뼈대를 만들어 줍니다.

`/tmp/lab` 폴더 안에 **`webapp`** 이라는 이름의 차트 뼈대를 만드세요.', '작업 위치가 `/tmp/lab` 이어야 합니다. 이름 앞에 경로를 줘도 돼요.', 'cd /tmp/lab && helm create webapp
ls webapp webapp/templates

# helm create 가 Chart.yaml, values.yaml, templates/ 를 만든다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\n"]', '["sh", "-c", "( grep -q \\"^name: webapp\\" /tmp/lab/webapp/Chart.yaml ) && ( [ -f /tmp/lab/webapp/values.yaml ] ) && ( [ -f /tmp/lab/webapp/templates/deployment.yaml ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Chart.yaml 의 이름이 webapp 이다", "cmd": ["sh", "-c", "grep -q \\"^name: webapp\\" /tmp/lab/webapp/Chart.yaml"]}, {"label": "values.yaml 이 있다", "cmd": ["sh", "-c", "[ -f /tmp/lab/webapp/values.yaml ]"]}, {"label": "templates 에 deployment.yaml 이 있다", "cmd": ["sh", "-c", "[ -f /tmp/lab/webapp/templates/deployment.yaml ]"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 2, '기본값 확인하기 (helm show values)', '**배경** — 차트를 쓰기 전에 **어떤 값을 바꿀 수 있는지** 는 `values.yaml` 에 있습니다. 차트 폴더(또는 저장소 차트)의 기본값은 `helm show values 차트` 로 볼 수 있습니다.

`/tmp/lab/demo` 차트의 기본값을 **`/tmp/q2.txt`** 에 저장하세요.', '`helm show` 아래의 하위 명령이에요.', 'helm show values /tmp/lab/demo > /tmp/q2.txt
cat /tmp/q2.txt

# show values 는 차트의 values.yaml 내용을 출력한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\n"]', '["sh", "-c", "( grep -q \\"greeting: hello-default\\" /tmp/q2.txt ) && ( grep -q \\"replicas: 1\\" /tmp/q2.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "기본 greeting 값이 들어 있다", "cmd": ["sh", "-c", "grep -q \\"greeting: hello-default\\" /tmp/q2.txt"]}, {"label": "기본 replicas 값이 들어 있다", "cmd": ["sh", "-c", "grep -q \\"replicas: 1\\" /tmp/q2.txt"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 3, '설치 없이 YAML 미리 보기 (helm template)', '**배경** — `helm template 릴리스이름 차트` 는 값을 틀에 넣어 **완성된 YAML 을 출력만** 합니다. 클러스터에 아무것도 만들지 않으므로 설치 전에 결과를 확인할 때 씁니다. 릴리스 이름은 틀의 `{{ .Release.Name }}` 자리에 들어갑니다.

릴리스 이름 **`rel3`** 로 `/tmp/lab/demo` 차트를 렌더링해 **`/tmp/q3.yaml`** 에 저장하세요.', '`helm template` 뒤에 릴리스 이름, 차트 경로 순서예요.', 'helm template rel3 /tmp/lab/demo > /tmp/q3.yaml
cat /tmp/q3.yaml

# template 은 렌더링만 한다. 릴리스 이름 rel3 이 ConfigMap 이름 rel3-config 에 들어간다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\n"]', '["sh", "-c", "( grep -q \\"kind: ConfigMap\\" /tmp/q3.yaml ) && ( grep -q \\"name: rel3-config\\" /tmp/q3.yaml ) && ( grep -q hello-default /tmp/q3.yaml )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ConfigMap 이 렌더링되었다", "cmd": ["sh", "-c", "grep -q \\"kind: ConfigMap\\" /tmp/q3.yaml"]}, {"label": "릴리스 이름이 들어갔다 (rel3-config)", "cmd": ["sh", "-c", "grep -q \\"name: rel3-config\\" /tmp/q3.yaml"]}, {"label": "기본 greeting 이 들어갔다", "cmd": ["sh", "-c", "grep -q hello-default /tmp/q3.yaml"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 4, '값 바꿔서 렌더링 (--set)', '**배경** — 기본값은 설치할 때 바꿀 수 있습니다. 가장 간단한 방법이 `--set 키=값` 입니다. 같은 키가 `values.yaml` 에도 있으면 `--set` 이 이깁니다.

릴리스 이름 `rel4` 로 `/tmp/lab/demo` 를 렌더링하되 **`greeting` 값을 `hi-etude` 로** 바꿔서 **`/tmp/q4.yaml`** 에 저장하세요. (클러스터에는 설치하지 않습니다.)', '`helm template rel4 차트 --set greeting=hi-etude` 처럼 씁니다.', 'helm template rel4 /tmp/lab/demo --set greeting=hi-etude > /tmp/q4.yaml
cat /tmp/q4.yaml

# --set 이 values.yaml 의 기본값보다 우선한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\n"]', '["sh", "-c", "( grep -q \\"greeting: \\\\\\"hi-etude\\\\\\"\\" /tmp/q4.yaml ) && ( ! grep -q hello-default /tmp/q4.yaml )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "greeting 이 hi-etude 로 렌더링되었다", "cmd": ["sh", "-c", "grep -q \\"greeting: \\\\\\"hi-etude\\\\\\"\\" /tmp/q4.yaml"]}, {"label": "기본값 hello-default 는 없다", "cmd": ["sh", "-c", "! grep -q hello-default /tmp/q4.yaml"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 5, '값 파일로 바꿔서 렌더링 (-f)', '**배경** — 바꿀 값이 여러 개이거나 환경(개발·운영)마다 다르면 값을 **파일** 로 두고 `-f 파일` 로 넘깁니다. 파일에는 바꿀 키만 적으면 되고 나머지는 차트 기본값을 씁니다.

운영용 값 파일 `/tmp/lab/prod.yaml` 이 있습니다. 릴리스 이름 `rel5` 로 `/tmp/lab/demo` 를 **이 값 파일을 적용해** 렌더링하고 **`/tmp/q5.yaml`** 에 저장하세요.', '`-f` 옵션 뒤에 값 파일 경로를 주세요. `cat /tmp/lab/prod.yaml` 로 먼저 내용을 볼 수 있어요.', 'helm template rel5 /tmp/lab/demo -f /tmp/lab/prod.yaml > /tmp/q5.yaml
cat /tmp/q5.yaml

# -f 로 넘긴 값이 기본값을 덮어쓴다. 값 파일에 없는 키는 기본값이 그대로다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\nprintf ''greeting: hello-prod\\\\nreplicas: 3\\\\n'' > /tmp/lab/prod.yaml\\n"]', '["sh", "-c", "( grep -q \\"greeting: \\\\\\"hello-prod\\\\\\"\\" /tmp/q5.yaml ) && ( grep -q \\"replicas: \\\\\\"3\\\\\\"\\" /tmp/q5.yaml )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "greeting 이 hello-prod 다", "cmd": ["sh", "-c", "grep -q \\"greeting: \\\\\\"hello-prod\\\\\\"\\" /tmp/q5.yaml"]}, {"label": "replicas 가 3 이다", "cmd": ["sh", "-c", "grep -q \\"replicas: \\\\\\"3\\\\\\"\\" /tmp/q5.yaml"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 6, '차트 오류 고치기 (helm lint)', '**배경** — `helm lint 차트` 는 차트 문법과 필수 항목을 **미리 점검** 합니다. 오류가 있으면 `[ERROR]` 로 알려 주고 종료 코드가 0 이 아니게 됩니다. 설치 전에 돌려 보는 습관이 좋습니다.

`/tmp/lab/broken` 차트가 `helm lint` 에서 오류를 냅니다. 원인을 찾아 **고쳐서 `helm lint` 가 통과하게** 하세요.', '`helm lint /tmp/lab/broken` 의 `[ERROR]` 줄을 읽어 보세요. `Chart.yaml` 의 필수 항목 하나가 빠져 있어요.', 'helm lint /tmp/lab/broken      # [ERROR] Chart.yaml: version is required
echo ''version: 0.1.0'' >> /tmp/lab/broken/Chart.yaml
helm lint /tmp/lab/broken

# Chart.yaml 에는 apiVersion, name, version 이 필수다. 빠진 version 을 추가한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/broken/templates\\nprintf ''apiVersion: v2\\\\nname: broken\\\\n'' > /tmp/lab/broken/Chart.yaml\\nprintf ''apiVersion: v1\\\\nkind: ConfigMap\\\\nmetadata:\\\\n  name: broken-cm\\\\ndata:\\\\n  a: b\\\\n'' > /tmp/lab/broken/templates/cm.yaml\\n"]', '["sh", "-c", "( helm lint /tmp/lab/broken >/dev/null 2>&1 ) && ( grep -q \\"^version:\\" /tmp/lab/broken/Chart.yaml ) && ( [ -f /tmp/lab/broken/templates/cm.yaml ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "helm lint 가 통과한다", "cmd": ["sh", "-c", "helm lint /tmp/lab/broken >/dev/null 2>&1"]}, {"label": "Chart.yaml 에 version 이 있다", "cmd": ["sh", "-c", "grep -q \\"^version:\\" /tmp/lab/broken/Chart.yaml"]}, {"label": "템플릿은 지워지지 않았다", "cmd": ["sh", "-c", "[ -f /tmp/lab/broken/templates/cm.yaml ]"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 7, '차트를 파일 하나로 묶기 (helm package)', '**배경** — 차트를 다른 사람이나 저장소에 전달하려면 `helm package 차트폴더` 로 **`.tgz` 파일** 하나로 묶습니다. 파일 이름은 `이름-버전.tgz` 이고, 버전은 `Chart.yaml` 의 `version` 입니다. `-d 폴더` 로 만들 위치를 정합니다.

`/tmp/lab/demo` 를 패키징해서 **`/tmp/pkg`** 폴더에 파일이 생기게 하세요.', '`-d /tmp/pkg` 옵션을 주면 그 폴더에 만들어요. 폴더가 없으면 먼저 만드세요.', 'mkdir -p /tmp/pkg
helm package /tmp/lab/demo -d /tmp/pkg
ls /tmp/pkg

# 이름-버전.tgz 가 만들어진다 (demo-0.1.0.tgz)', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\n"]', '["sh", "-c", "( [ -s /tmp/pkg/demo-0.1.0.tgz ] ) && ( tar -tzf /tmp/pkg/demo-0.1.0.tgz | grep -q demo/Chart.yaml )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "demo-0.1.0.tgz 가 만들어졌다", "cmd": ["sh", "-c", "[ -s /tmp/pkg/demo-0.1.0.tgz ]"]}, {"label": "패키지 안에 Chart.yaml 이 있다", "cmd": ["sh", "-c", "tar -tzf /tmp/pkg/demo-0.1.0.tgz | grep -q demo/Chart.yaml"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 8, '로컬 차트를 클러스터에 설치 (helm install)', '**배경** — 저장소에서 받지 않고 **로컬 폴더의 차트** 도 그대로 설치할 수 있습니다. 설치하면 **릴리스(release)** 가 만들어지고, 차트의 YAML 이 클러스터에 적용됩니다.

`/tmp/lab/demo` 차트를 릴리스 이름 **`rel8`** 로 설치하되 **`greeting` 을 `hi-etude` 로** 바꾸세요.', '`helm install 릴리스이름 차트경로 --set 키=값` 입니다. 확인은 `helm list` 와 `kubectl get configmap`.', 'helm install rel8 /tmp/lab/demo --set greeting=hi-etude
helm list
kubectl get configmap rel8-config -o jsonpath=''{.data.greeting}''

# 릴리스 이름 rel8 → ConfigMap rel8-config. --set 으로 greeting 이 바뀐다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\n"]', '["sh", "-c", "( helm list -q | grep -qx rel8 ) && ( [ \\"$(kubectl get configmap rel8-config -o jsonpath={.data.greeting})\\" = hi-etude ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "릴리스 rel8 이 설치되어 있다", "cmd": ["sh", "-c", "helm list -q | grep -qx rel8"]}, {"label": "ConfigMap 의 greeting 이 hi-etude 다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap rel8-config -o jsonpath={.data.greeting})\\" = hi-etude ]"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 9, '업그레이드하고 이전으로 되돌리기 (helm rollback)', '**배경** — 릴리스는 `upgrade` 때마다 **리비전(revision)** 이 하나씩 늘어 `helm history` 에 남습니다. 문제가 생기면 `helm rollback 릴리스 리비전번호` 로 그 시점 설정으로 돌립니다. 되돌려도 이력은 지워지지 않고 **새 리비전이 하나 더** 생깁니다.

릴리스 `rel9` 는 리비전 1(`greeting=v1`) 뒤에 리비전 2(`greeting=v2`)로 업그레이드되어 있습니다. **리비전 1 로 되돌리세요.**', '먼저 `helm history rel9` 로 리비전 번호를 확인하세요. 되돌린 뒤 greeting 이 v1 로 보이면 성공이에요.', 'helm history rel9
helm rollback rel9 1
helm history rel9
kubectl get configmap rel9-config -o jsonpath=''{.data.greeting}''

# 리비전 1 로 rollback 하면 greeting 이 v1 로 돌아오고 이력에는 리비전 3 이 추가된다', '["sh", "-c", "rm -rf /tmp/lab /tmp/q*.yaml /tmp/q*.txt /tmp/pkg; mkdir -p /tmp/lab; helm uninstall rel8 >/dev/null 2>&1; helm uninstall rel9 >/dev/null 2>&1; true\\nmkdir -p /tmp/lab/demo/templates\\ncat > /tmp/lab/demo/Chart.yaml <<''EOF''\\napiVersion: v2\\nname: demo\\ndescription: etude practice chart\\nversion: 0.1.0\\nappVersion: \\"1.0\\"\\nEOF\\ncat > /tmp/lab/demo/values.yaml <<''EOF''\\ngreeting: hello-default\\nreplicas: 1\\nEOF\\ncat > /tmp/lab/demo/templates/configmap.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: {{ .Release.Name }}-config\\ndata:\\n  greeting: {{ .Values.greeting | quote }}\\n  replicas: {{ .Values.replicas | quote }}\\nEOF\\nhelm install rel9 /tmp/lab/demo --set greeting=v1 >/dev/null && helm upgrade rel9 /tmp/lab/demo --set greeting=v2 >/dev/null\\n"]', '["sh", "-c", "( [ \\"$(kubectl get configmap rel9-config -o jsonpath={.data.greeting})\\" = v1 ] ) && ( [ \\"$(helm history rel9 | tail -n +2 | wc -l | tr -d \\" \\")\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ConfigMap 의 greeting 이 v1 로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap rel9-config -o jsonpath={.data.greeting})\\" = v1 ]"]}, {"label": "이력이 3 개 리비전이다 (되돌려도 이력은 남는다)", "cmd": ["sh", "-c", "[ \\"$(helm history rel9 | tail -n +2 | wc -l | tr -d \\" \\")\\" = 3 ]"]}]', '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 10, '값이 겹칠 때 누가 이길까?', '차트의 `values.yaml` 에 `greeting: A`, `-f prod.yaml` 에 `greeting: B`, 명령줄 `--set greeting=C` 가 모두 있을 때 최종 값은 무엇일까요?', 'Helm 문서의 "specificity" 순서를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["A (차트 기본값이 가장 우선한다)", "C (--set 이 가장 우선한다)", "B (-f 값 파일이 가장 우선한다)", "값이 겹치면 오류가 나서 설치할 수 없다"]', 1, 'Helm 문서는 값의 우선순위를 차트의 values.yaml(기본) < 사용자가 준 값 파일(-f) < `--set` 순으로 설명하며, `--set` 이 가장 높습니다. 그래서 최종 값은 C 입니다.', NULL, NULL, NULL, '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 11, '설치 전에 문법 점검', '차트 폴더 `./demo` 의 문법과 필수 항목을 **설치 전에 점검** 하는 명령입니다. 빈칸을 채우세요.', '"보푸라기를 터는 도구"라는 이름이에요.', NULL, NULL, '[]', 'fill', '["lint", "check", "verify", "test"]', NULL, '`helm lint 차트` 는 차트의 문제를 점검해 `[ERROR]`, `[WARNING]` 으로 알려 줍니다. `helm test` 는 설치된 릴리스에 딸린 테스트를 실행하는 명령이라 점검과 다릅니다. `verify` 는 패키지 서명 검증이고 `check` 는 helm 하위 명령이 아닙니다.', '[0]', 'helm {0} ./demo', NULL, '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 383, 12, '차트 만들어 설치하기', '차트를 직접 만들어서 클러스터에 설치하기까지의 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 고치기 → 점검 → 미리 보기 → 설치 순서예요.', NULL, NULL, '[]', 'order', '["`helm create` 로 차트 뼈대를 만든다", "`values.yaml` 과 `templates/` 를 목적에 맞게 고친다", "`helm lint` 로 점검하고 `helm template` 으로 결과를 미리 본다", "`helm install` 로 클러스터에 설치한다"]', NULL, '뼈대를 만들고 값과 틀을 고친 뒤, 설치 전에 `lint` 와 `template` 으로 확인하고 마지막에 `install` 합니다. 설치 뒤에는 `helm list`, `helm status` 로 확인합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "helm create", "url": "https://helm.sh/docs/helm/helm_create/"}, {"title": "helm template", "url": "https://helm.sh/docs/helm/helm_template/"}, {"title": "helm lint", "url": "https://helm.sh/docs/helm/helm_lint/"}, {"title": "helm package", "url": "https://helm.sh/docs/helm/helm_package/"}, {"title": "helm install", "url": "https://helm.sh/docs/helm/helm_install/"}, {"title": "helm rollback", "url": "https://helm.sh/docs/helm/helm_rollback/"}, {"title": "Helm 값 파일 가이드", "url": "https://helm.sh/docs/chart_template_guide/values_files/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 383 AND order_index = 12);

